-- Web Empire — Non-AI catalog growth wave 2 (social-media-tools)
begin;
create temporary table social_media_tools_w2 (slug text primary key,title_ar text not null,title_en text not null,description_ar text not null,description_en text not null,operations jsonb not null,schema_kind text not null check (schema_kind in ('one','aux','case','style')),input_ar text not null,input_en text not null,submit_ar text not null,submit_en text not null,max_length integer not null,aux_key text,aux_ar text,aux_en text,aux_ph_ar text,aux_ph_en text,sort_order integer not null) on commit drop;
create temporary table social_media_tools_w2_ready as select seed.*,
jsonb_build_object('fields',case seed.schema_kind when 'one' then jsonb_build_array(jsonb_build_object('key','text','label',seed.input_ar,'type','textarea','required',true,'placeholder','أدخل النص هنا...','maxLength',seed.max_length)) when 'case' then jsonb_build_array(jsonb_build_object('key','text','label',seed.input_ar,'type','textarea','required',true,'placeholder','أدخل النص هنا...','maxLength',seed.max_length),jsonb_build_object('key','mode','label','الحالة','type','select','required',true,'defaultValue','lowercase','options','[{"value":"uppercase","label":"أحرف كبيرة"},{"value":"lowercase","label":"أحرف صغيرة"},{"value":"title","label":"حالة العنوان"},{"value":"sentence","label":"حالة الجملة"}]'::jsonb)) else jsonb_build_array(jsonb_build_object('key','text','label',seed.input_ar,'type','textarea','required',true,'placeholder','أدخل النص هنا...','maxLength',seed.max_length),jsonb_build_object('key','style','label','النمط','type','select','required',true,'defaultValue','sparkles','options','[{"value":"stars","label":"نجوم"},{"value":"sparkles","label":"لمعان"},{"value":"hearts","label":"قلوب"},{"value":"brackets","label":"أقواس"},{"value":"quotes","label":"اقتباس"},{"value":"arrows","label":"أسهم"}]'::jsonb)) end,'submitLabel',seed.submit_ar) schema_ar,
jsonb_build_object('fields',case seed.schema_kind when 'one' then jsonb_build_array(jsonb_build_object('key','text','label',seed.input_en,'type','textarea','required',true,'placeholder','Enter text here...','maxLength',seed.max_length)) when 'case' then jsonb_build_array(jsonb_build_object('key','text','label',seed.input_en,'type','textarea','required',true,'placeholder','Enter text here...','maxLength',seed.max_length),jsonb_build_object('key','mode','label','Case','type','select','required',true,'defaultValue','lowercase','options','[{"value":"uppercase","label":"UPPERCASE"},{"value":"lowercase","label":"lowercase"},{"value":"title","label":"Title Case"},{"value":"sentence","label":"Sentence case"}]'::jsonb)) else jsonb_build_array(jsonb_build_object('key','text','label',seed.input_en,'type','textarea','required',true,'placeholder','Enter text here...','maxLength',seed.max_length),jsonb_build_object('key','style','label','Style','type','select','required',true,'defaultValue','sparkles','options','[{"value":"stars","label":"Stars"},{"value":"sparkles","label":"Sparkles"},{"value":"hearts","label":"Hearts"},{"value":"brackets","label":"Brackets"},{"value":"quotes","label":"Quotes"},{"value":"arrows","label":"Arrows"}]'::jsonb)) end,'submitLabel',seed.submit_en) schema_en from social_media_tools_w2 seed;
select s.slug,s.title_ar,s.title_en,s.description_ar,c.id,'text_transform'::public.tool_engine_type,s.schema_ar,'{}'::jsonb,jsonb_build_object('input_key','text','operations',s.operations),'primary_with_fallback'::public.provider_strategy_type,null,null,'free'::public.pricing_mode_type,0,0,1,false,false,true,s.sort_order,s.title_ar,s.description_ar from social_media_tools_w2_ready s join public.categories c on c.slug='social-media-tools'
on conflict(slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,short_description=excluded.short_description,category_id=excluded.category_id,engine_type=excluded.engine_type,input_schema=excluded.input_schema,output_schema=excluded.output_schema,runtime_config=excluded.runtime_config,model_alias=null,prompt_template=null,pricing_mode='free'::public.pricing_mode_type,fixed_points=0,minimum_points=0,cost_multiplier=1,requires_auth=false,is_featured=false,is_active=true,sort_order=excluded.sort_order,seo_title=excluded.seo_title,seo_description=excluded.seo_description,updated_at=now();
commit;